class Solver:
    def solve(self, problem, **kwargs):
        chacha = openssl.aead.ChaCha20Poly1305(problem["key"])
        out = bytearray(len(problem["plaintext"]) + 16)
        chacha.encrypt_into(problem["nonce"], problem["plaintext"], problem["associated_data"], out)
